"""Toy Pipecat-style voice pipeline: VAD  STT  LLM  TTS  transport.

Frames travel DOWNSTREAM (source to sink) and UPSTREAM (cancel/control).
A scripted input shows normal flow plus a barge-in cancel that stops TTS.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass
class Frame:
    kind: str
    payload: Any
    direction: str = "downstream"


class Processor:
    def __init__(self, name: str) -> None:
        self.name = name
        self.next: Processor | None = None
        self.prev: Processor | None = None
        self.trace: list[str] = []

    def process(self, frame: Frame) -> None:
        self.trace.append(f"{self.name} saw {frame.kind}")
        if self.next is not None and frame.direction == "downstream":
            self.next.process(frame)
        elif self.prev is not None and frame.direction == "upstream":
            self.prev.process(frame)


class VAD(Processor):
    def process(self, frame: Frame) -> None:
        if frame.kind == "audio_chunk":
            is_speech = bool(frame.payload)
            self.trace.append(f"VAD: speech={is_speech}")
            if is_speech:
                super().process(Frame("vad_speech", frame.payload))
        else:
            super().process(frame)


class STT(Processor):
    def process(self, frame: Frame) -> None:
        if frame.kind == "vad_speech":
            transcript = str(frame.payload)
            self.trace.append(f"STT: -> {transcript!r}")
            super().process(Frame("transcript", transcript))
        else:
            super().process(frame)


class LLM(Processor):
    def __init__(self, name: str, replies: dict[str, str]) -> None:
        super().__init__(name)
        self.replies = replies

    def process(self, frame: Frame) -> None:
        if frame.kind == "cancel":
            self.trace.append("LLM: cancelled")
            super().process(frame)
            return
        if frame.kind == "transcript":
            text = str(frame.payload)
            reply = self.replies.get(text, "[no canned reply]")
            self.trace.append(f"LLM: {text!r}  -> {reply!r}")
            super().process(Frame("text", reply))
        else:
            super().process(frame)


class TTS(Processor):
    def __init__(self, name: str) -> None:
        super().__init__(name)
        self.cancelled = False

    def process(self, frame: Frame) -> None:
        if frame.kind == "cancel":
            self.cancelled = True
            self.trace.append("TTS: cancel received; drop pending audio")
            super().process(frame)
            return
        if frame.kind == "text":
            self.cancelled = False
            words = str(frame.payload).split()
            emitted: list[str] = []
            for w in words:
                if self.cancelled:
                    self.trace.append(f"TTS: cut mid-word after {emitted}")
                    break
                emitted.append(w)
            self.trace.append(f"TTS: emitted {emitted}")
            super().process(Frame("tts_audio", emitted))
        else:
            super().process(frame)


class Transport(Processor):
    def __init__(self, name: str) -> None:
        super().__init__(name)
        self.delivered: list[list[str]] = []

    def process(self, frame: Frame) -> None:
        if frame.kind == "tts_audio":
            self.delivered.append(list(frame.payload))
            self.trace.append(f"transport: sent {len(frame.payload)} words")
        else:
            super().process(frame)


def link(*processors: Processor) -> None:
    for a, b in zip(processors, processors[1:]):
        a.next = b
        b.prev = a


def main() -> None:
    print("=" * 70)
    print("VOICE PIPELINE (PIPECAT-SHAPED): Phase 14, Lesson 22")
    print("=" * 70)

    vad = VAD("vad")
    stt = STT("stt")
    llm = LLM("llm", replies={
        "hello": "hi there, how can I help today?",
        "refund please": (
            "sure, I can help with a refund; what order number should I look up?"
        ),
    })
    tts = TTS("tts")
    transport = Transport("transport")
    link(vad, stt, llm, tts, transport)

    print("\nscenario 1: normal flow")
    vad.process(Frame("audio_chunk", "hello"))
    print(f"  transport delivered: {transport.delivered[-1]}")

    print("\nscenario 2: barge-in mid-utterance")
    tts.cancelled = False
    vad.process(Frame("audio_chunk", "refund please"))
    transport.process(Frame("cancel", None, direction="upstream"))

    print("  trace across pipeline")
    for proc in (vad, stt, llm, tts, transport):
        for line in proc.trace:
            print(f"    {proc.name}: {line}")

    print()
    print("barge-in needs UPSTREAM cancel frames that propagate back to TTS+LLM.")
    print("sum latency per stage; premium stack lands at 450-600ms end-to-end.")


if __name__ == "__main__":
    main()

// Lesson: Voice Agents: Pipecat and LiveKit (phase 14 / lesson 22)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/14-agent-engineering/22-voice-agents-pipecat-livekit/docs/en.md
// Run: npx tsx phases/14-agent-engineering/22-voice-agents-pipecat-livekit/code/main.ts

function pyStr(s: string): string {
  if (s.includes("'") && !s.includes('"')) return `"${s}"`;
  return `'${s.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
}

function pyList(xs: string[]): string {
  return "[" + xs.map(pyStr).join(", ") + "]";
}

function splitWords(s: string): string[] {
  return s.split(/\s+/).filter((w) => w.length > 0);
}

class Frame {
  constructor(
    public kind: string,
    public payload: unknown,
    public direction = "downstream",
  ) {}
}

class Processor {
  next: Processor | null = null;
  prev: Processor | null = null;
  trace: string[] = [];

  constructor(public name: string) {}

  process(frame: Frame): void {
    this.trace.push(`${this.name} saw ${frame.kind}`);
    if (this.next !== null && frame.direction === "downstream") {
      this.next.process(frame);
    } else if (this.prev !== null && frame.direction === "upstream") {
      this.prev.process(frame);
    }
  }
}

class VAD extends Processor {
  override process(frame: Frame): void {
    if (frame.kind === "audio_chunk") {
      const isSpeech = Boolean(frame.payload);
      this.trace.push(`VAD: speech=${isSpeech ? "True" : "False"}`);
      if (isSpeech) super.process(new Frame("vad_speech", frame.payload));
    } else {
      super.process(frame);
    }
  }
}

class STT extends Processor {
  override process(frame: Frame): void {
    if (frame.kind === "vad_speech") {
      const transcript = String(frame.payload);
      this.trace.push(`STT: -> ${pyStr(transcript)}`);
      super.process(new Frame("transcript", transcript));
    } else {
      super.process(frame);
    }
  }
}

class LLM extends Processor {
  constructor(
    name: string,
    public replies: Map<string, string>,
  ) {
    super(name);
  }

  override process(frame: Frame): void {
    if (frame.kind === "cancel") {
      this.trace.push("LLM: cancelled");
      super.process(frame);
      return;
    }
    if (frame.kind === "transcript") {
      const text = String(frame.payload);
      const reply = this.replies.get(text) ?? "[no canned reply]";
      this.trace.push(`LLM: ${pyStr(text)}  -> ${pyStr(reply)}`);
      super.process(new Frame("text", reply));
    } else {
      super.process(frame);
    }
  }
}

class TTS extends Processor {
  cancelled = false;

  override process(frame: Frame): void {
    if (frame.kind === "cancel") {
      this.cancelled = true;
      this.trace.push("TTS: cancel received; drop pending audio");
      super.process(frame);
      return;
    }
    if (frame.kind === "text") {
      this.cancelled = false;
      const words = splitWords(String(frame.payload));
      const emitted: string[] = [];
      for (const w of words) {
        if (this.cancelled) {
          this.trace.push(`TTS: cut mid-word after ${pyList(emitted)}`);
          break;
        }
        emitted.push(w);
      }
      this.trace.push(`TTS: emitted ${pyList(emitted)}`);
      super.process(new Frame("tts_audio", emitted));
    } else {
      super.process(frame);
    }
  }
}

class Transport extends Processor {
  delivered: string[][] = [];

  override process(frame: Frame): void {
    if (frame.kind === "tts_audio") {
      const payload = frame.payload as string[];
      this.delivered.push([...payload]);
      this.trace.push(`transport: sent ${payload.length} words`);
    } else {
      super.process(frame);
    }
  }
}

function link(...processors: Processor[]): void {
  for (let i = 0; i + 1 < processors.length; i++) {
    const a = processors[i]!;
    const b = processors[i + 1]!;
    a.next = b;
    b.prev = a;
  }
}

function main(): void {
  console.log("=".repeat(70));
  console.log("VOICE PIPELINE (PIPECAT-SHAPED): Phase 14, Lesson 22");
  console.log("=".repeat(70));

  const vad = new VAD("vad");
  const stt = new STT("stt");
  const llm = new LLM(
    "llm",
    new Map([
      ["hello", "hi there, how can I help today?"],
      ["refund please", "sure, I can help with a refund; what order number should I look up?"],
    ]),
  );
  const tts = new TTS("tts");
  const transport = new Transport("transport");
  link(vad, stt, llm, tts, transport);

  console.log("\nscenario 1: normal flow");
  vad.process(new Frame("audio_chunk", "hello"));
  console.log(`  transport delivered: ${pyList(transport.delivered[transport.delivered.length - 1]!)}`);

  console.log("\nscenario 2: barge-in mid-utterance");
  tts.cancelled = false;
  vad.process(new Frame("audio_chunk", "refund please"));
  transport.process(new Frame("cancel", null, "upstream"));

  console.log("  trace across pipeline");
  for (const proc of [vad, stt, llm, tts, transport]) {
    for (const line of proc.trace) console.log(`    ${proc.name}: ${line}`);
  }

  console.log();
  console.log("barge-in needs UPSTREAM cancel frames that propagate back to TTS+LLM.");
  console.log("sum latency per stage; premium stack lands at 450-600ms end-to-end.");
}

main();
